app_css:
.tool-app-tippool { color: #3f2d12; max-width: 860px; margin-inline: auto; }
.tool-app-tippool .tp-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px; margin: 12px 0; }
.tool-app-tippool label { display: flex; flex-direction: column; font-size: 12px; font-weight: 600; gap: 4px; }
.tool-app-tippool input[type='text'], .tool-app-tippool input[type='number'], .tool-app-tippool input[type='date'], .tool-app-tippool select { border: 1px solid #f3d9a4; border-radius: 8px; padding: 8px 10px; font-size: 14px; width: 100%; box-sizing: border-box; background: #fff; }
.tool-app-tippool .tp-totalrow { display: flex; justify-content: space-between; align-items: center; background: #fef6e7; border-radius: 10px; padding: 10px 14px; margin: 10px 0; font-size: 16px; }
.tool-app-tippool .tp-table { width: 100%; border-collapse: collapse; margin: 8px 0; }
.tool-app-tippool .tp-table th { text-align: left; font-size: 12px; color: #8a6d3b; padding: 6px; }
.tool-app-tippool .tp-table td { padding: 4px; border-top: 1px solid #f3e3c3; }
.tool-app-tippool .tp-hours { max-width: 80px; }
.tool-app-tippool .tp-share { font-weight: 700; white-space: nowrap; }
.tool-app-tippool .tp-remove { background: none; border: none; color: #b91c1c; font-size: 20px; cursor: pointer; }
.tool-app-tippool .tp-btn { background: #B45309; color: #fff; border: none; border-radius: 10px; padding: 10px 18px; font-size: 14px; font-weight: 700; cursor: pointer; }
.tool-app-tippool .tp-btn:hover { background: #92400e; }
.tool-app-tippool .tp-btn-ghost { background: #fef3e2; color: #B45309; }
.tool-app-tippool .tp-btn-ghost:hover { background: #fde8c9; }
.tool-app-tippool .tp-breakdown { background: #fffdf7; border: 1px solid #f3e3c3; border-radius: 10px; padding: 12px 14px; margin: 8px 0; font-size: 14px; }
.tool-app-tippool .tp-breakdown .tp-row { display: flex; justify-content: space-between; padding: 4px 0; }
.tool-app-tippool .tp-breakdown .tp-note { color: #8a6d3b; font-size: 12px; margin-top: 6px; }
.tool-app-tippool .tp-muted { color: #8a6d3b; margin: 0; }
.tool-app-tippool .tp-actions { display: flex; gap: 10px; margin: 14px 0; flex-wrap: wrap; }
.tool-app-tippool .tp-saved { list-style: none; padding: 0; margin: 8px 0; }
.tool-app-tippool .tp-saved li { display: flex; justify-content: space-between; align-items: center; background: #fffdf7; border: 1px solid #f3e3c3; border-radius: 8px; padding: 8px 12px; margin-bottom: 6px; font-size: 14px; }
.tool-app-tippool .tp-saved button.tp-load { background: none; border: none; color: #B45309; font-weight: 700; cursor: pointer; text-align: left; }
.tool-app-tippool .tp-saved button.tp-del { background: none; border: none; color: #b91c1c; cursor: pointer; font-size: 18px; }
.tool-app-tippool .tool-print-doc { display: none; }
@media print {
  .tool-app-tippool .tp-screen { display: none !important; }
  .tool-app-tippool .tool-print-doc { display: block !important; color: #000; }
  .tool-app-tippool .tool-print-doc table { width: 100%; border-collapse: collapse; margin: 12px 0; }
  .tool-app-tippool .tool-print-doc th, .tool-app-tippool .tool-print-doc td { border: 1px solid #999; padding: 6px; text-align: left; font-size: 13px; }
}

app_js:
(function () {
  'use strict';
  function $(id) { return document.getElementById(id); }
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function num(v) { v = parseFloat(v); return isFinite(v) && v > 0 ? v : 0; }
  function money(n) { return '$' + (isFinite(n) ? n : 0).toFixed(2); }
  var root = $('toolAppRoot');
  var tbody = $('tp-staff');
  var LS_KEY = 'toolapp-tippool-nights';
  function addStaff(name, role, hours) {
    var tr = document.createElement('tr');
    tr.className = 'tp-person';
    var sel = document.createElement('select');
    sel.className = 'tp-role';
    var o1 = document.createElement('option'); o1.value = 'tipped'; o1.textContent = 'Tipped (server, bartender)';
    var o2 = document.createElement('option'); o2.value = 'support'; o2.textContent = 'Support (bar, busser, host)';
    sel.appendChild(o1); sel.appendChild(o2);
    sel.value = role === 'support' ? 'support' : 'tipped';
    var tdName = document.createElement('td');
    var inpName = document.createElement('input');
    inpName.type = 'text'; inpName.className = 'tp-name'; inpName.placeholder = 'Name';
    inpName.value = name || '';
    tdName.appendChild(inpName);
    var tdRole = document.createElement('td'); tdRole.appendChild(sel);
    var tdHours = document.createElement('td');
    var inpHours = document.createElement('input');
    inpHours.type = 'number'; inpHours.className = 'tp-hours'; inpHours.min = '0'; inpHours.step = '0.25';
    inpHours.value = hours == null ? 8 : hours;
    tdHours.appendChild(inpHours);
    var tdShare = document.createElement('td'); tdShare.className = 'tp-share'; tdShare.textContent = '$0.00';
    var tdX = document.createElement('td');
    var btn = document.createElement('button');
    btn.type = 'button'; btn.className = 'tp-remove'; btn.setAttribute('aria-label', 'Remove person');
    btn.textContent = '\u00d7';
    tdX.appendChild(btn);
    tr.appendChild(tdName); tr.appendChild(tdRole); tr.appendChild(tdHours); tr.appendChild(tdShare); tr.appendChild(tdX);
    tbody.appendChild(tr);
    recalc();
  }
  function readStaff() {
    var out = [];
    var rows = tbody.querySelectorAll('tr.tp-person');
    for (var i = 0; i < rows.length; i++) {
      out.push({
        row: rows[i],
        name: rows[i].querySelector('.tp-name').value,
        role: rows[i].querySelector('.tp-role').value,
        hours: num(rows[i].querySelector('.tp-hours').value)
      });
    }
    return out;
  }
  function splitCents(poolCents, weights) {
    var total = 0, i;
    for (i = 0; i < weights.length; i++) total += weights[i];
    var shares = [];
    if (!weights.length || total <= 0 || poolCents <= 0) {
      for (i = 0; i < weights.length; i++) shares.push(0);
      return shares;
    }
    var acc = 0;
    for (i = 0; i < weights.length; i++) {
      var exact = poolCents * weights[i] / total;
      var c = Math.floor(exact);
      shares.push(c);
      acc += c;
    }
    var leftover = Math.round(poolCents - acc);
    i = 0;
    while (leftover > 0 && weights.length) {
      if (weights[i % weights.length] > 0) { shares[i % weights.length] += 1; leftover -= 1; }
      i++;
      if (i > weights.length * 4) break;
    }
    return shares;
  }
  function compute() {
    var total = num($('tp-cash').value) + num($('tp-card').value);
    var pct = Math.min(100, Math.max(0, num($('tp-supportpct').value)));
    var staff = readStaff();
    var tipped = staff.filter(function (s) { return s.role === 'tipped'; });
    var support = staff.filter(function (s) { return s.role === 'support'; });
    var totalCents = Math.round(total * 100);
    var supportPool = tipped.length && support.length ? Math.round(totalCents * pct / 100) : (support.length ? totalCents : 0);
    var tippedPool = totalCents - supportPool;
    var supportShares = splitCents(supportPool, support.map(function (s) { return s.hours; }));
    var tippedShares = splitCents(tippedPool, tipped.map(function (s) { return s.hours; }));
    var i;
    for (i = 0; i < support.length; i++) support[i].cents = supportShares[i];
    for (i = 0; i < tipped.length; i++) tipped[i].cents = tippedShares[i];
    return { totalCents: totalCents, pct: pct, supportPool: supportPool, tippedPool: tippedPool, tipped: tipped, support: support };
  }
  function recalc() {
    var c = compute();
    $('tp-total').textContent = money(c.totalCents / 100);
    var rows = tbody.querySelectorAll('tr.tp-person');
    for (var i = 0; i < rows.length; i++) {
      rows[i].querySelector('.tp-share').textContent = '$0.00';
    }
    c.support.concat(c.tipped).forEach(function (s) {
      s.row.querySelector('.tp-share').textContent = money(s.cents / 100);
    });
    var bd = $('tp-breakdown');
    if (!c.tipped.length && !c.support.length) {
      bd.innerHTML = '<p class=\'tp-muted\'>Add staff to see each person\'s share.</p>';
      renderPrintDoc(c);
      return;
    }
    var html = '';
    html += '<div class=\'tp-row\'><span>Support pool (' + c.pct + '% of tips, ' + c.support.length + ' staff)</span><strong>' + money(c.supportPool / 100) + '</strong></div>';
    html += '<div class=\'tp-row\'><span>Tipped pool (' + c.tipped.length + ' staff)</span><strong>' + money(c.tippedPool / 100) + '</strong></div>';
    if (!c.support.length && c.pct > 0) html += '<p class=\'tp-note\'>No support staff listed, so the full pool goes to tipped staff.</p>';
    if (!c.tipped.length) html += '<p class=\'tp-note\'>No tipped staff listed, so the full pool goes to support staff.</p>';
    html += '<p class=\'tp-note\'>Shares are split by hours worked and rounded to the cent, so payouts always add up to the exact total.</p>';
    bd.innerHTML = html;
    renderPrintDoc(c);
  }
  function renderPrintDoc(c) {
    var rowsHtml = '';
    var all = c.support.concat(c.tipped);
    for (var i = 0; i < all.length; i++) {
      var s = all[i];
      rowsHtml += '<tr><td>' + esc(s.name || 'Unnamed') + '</td><td>' + (s.role === 'support' ? 'Support' : 'Tipped') + '</td><td>' + s.hours + '</td><td>' + money(s.cents / 100) + '</td></tr>';
    }
    $('tp-printdoc').innerHTML =
      '<h1>Tip-Out Sheet</h1>' +
      '<p><strong>Date:</strong> ' + esc($('tp-date').value) + '<br>' +
      '<strong>Total tips:</strong> ' + money(c.totalCents / 100) + ' (cash ' + money(num($('tp-cash').value)) + ', card ' + money(num($('tp-card').value)) + ')<br>' +
      '<strong>Tip-out rate:</strong> ' + c.pct + '%</p>' +
      '<table><thead><tr><th>Name</th><th>Role</th><th>Hours</th><th>Share</th></tr></thead>' +
      '<tbody>' + rowsHtml + '</tbody></table>' +
      '<p><strong>Support pool:</strong> ' + money(c.supportPool / 100) + '<br>' +
      '<strong>Tipped pool:</strong> ' + money(c.tippedPool / 100) + '</p>';
  }
  function getNights() {
    try { return JSON.parse(localStorage.getItem(LS_KEY)) || []; } catch (e) { return []; }
  }
  function setNights(n) {
    try { localStorage.setItem(LS_KEY, JSON.stringify(n)); } catch (e) {}
  }
  function saveNight() {
    var c = compute();
    var staff = readStaff().map(function (s) { return { name: s.name, role: s.role, hours: s.hours }; });
    var nights = getNights();
    nights.unshift({
      date: $('tp-date').value, cash: $('tp-cash').value, card: $('tp-card').value,
      pct: $('tp-supportpct').value, staff: staff,
      total: c.totalCents / 100, savedAt: new Date().toISOString()
    });
    setNights(nights.slice(0, 50));
    renderSaved();
  }
  function renderSaved() {
    var nights = getNights();
    var ul = $('tp-saved');
    ul.innerHTML = '';
    if (!nights.length) {
      var li = document.createElement('li');
      li.textContent = 'No saved nights yet.';
      ul.appendChild(li);
      return;
    }
    nights.forEach(function (item, idx) {
      var li = document.createElement('li');
      var load = document.createElement('button');
      load.type = 'button'; load.className = 'tp-load';
      load.setAttribute('data-idx', idx);
      load.textContent = (item.date || 'No date') + ' \u2014 ' + (item.staff ? item.staff.length : 0) + ' staff \u2014 ' + money(item.total);
      var del = document.createElement('button');
      del.type = 'button'; del.className = 'tp-del';
      del.setAttribute('data-idx', idx); del.setAttribute('aria-label', 'Delete night');
      del.textContent = '\u00d7';
      li.appendChild(load); li.appendChild(del);
      ul.appendChild(li);
    });
  }
  function loadNight(idx) {
    var item = getNights()[idx];
    if (!item) return;
    $('tp-date').value = item.date || '';
    $('tp-cash').value = item.cash || '';
    $('tp-card').value = item.card || '';
    $('tp-supportpct').value = item.pct == null ? 10 : item.pct;
    tbody.innerHTML = '';
    (item.staff || []).forEach(function (s) { addStaff(s.name, s.role, s.hours); });
    if (!(item.staff || []).length) addStaff('', 'tipped', 8);
    recalc();
  }
  root.addEventListener('input', function () { recalc(); });
  root.addEventListener('change', function () { recalc(); });
  root.addEventListener('click', function (e) {
    var t = e.target;
    if (t.id === 'tp-add') { addStaff('', 'tipped', 8); return; }
    if (t.id === 'tp-print') { recalc(); window.print(); return; }
    if (t.id === 'tp-save') { saveNight(); return; }
    if (t.classList && t.classList.contains('tp-remove')) { t.closest('tr').remove(); recalc(); return; }
    if (t.classList && t.classList.contains('tp-load')) { loadNight(parseInt(t.getAttribute('data-idx'), 10)); return; }
    if (t.classList && t.classList.contains('tp-del')) {
      var nights = getNights();
      nights.splice(parseInt(t.getAttribute('data-idx'), 10), 1);
      setNights(nights);
      renderSaved();
    }
  });
  (function init() {
    $('tp-date').value = new Date().toISOString().slice(0, 10);
    addStaff('', 'tipped', 8);
    addStaff('', 'tipped', 8);
    addStaff('', 'support', 8);
    renderSaved();
    recalc();
  })();
})();
